import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Privacy model","description":"Clash for iOS uses a local-first privacy model: profiles, logs and diagnostics stay on the device, and network requests serve features you configure or start.","frontmatter":{"title":"Privacy model","description":"Clash for iOS uses a local-first privacy model: profiles, logs and diagnostics stay on the device, and network requests serve features you configure or start.","keywords":["Clash privacy","iOS proxy privacy","VPN data collection","on-device processing","NetworkExtension privacy"],"jsonLd":{"@context":"https://schema.org","@type":"TechArticle","headline":"Clash's local-first privacy model","description":"What Clash keeps on the device and which external requests are configured or started by the user.","url":"https://clash.md/guide/privacy-model","inLanguage":"en-US","about":["on-device data processing","VPN privacy","user-directed network requests"]}},"headers":[],"relativePath":"guide/privacy-model.md","filePath":"guide/privacy-model.md","lastUpdated":1785318168000}`),a={name:`guide/privacy-model.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="privacy-model" tabindex="-1">Privacy model <a class="header-anchor" href="#privacy-model" aria-label="Permalink to “Privacy model”">​</a></h1><p>Clash is an on-device client. You configure the subscriptions, servers, and network services you choose, while its account-free architecture keeps the experience local-first.</p><h2 id="on-your-device" tabindex="-1">On your device <a class="header-anchor" href="#on-your-device" aria-label="Permalink to “On your device”">​</a></h2><p>Profiles, settings, connection history, logs, and diagnostics are handled locally. Sensitive local proxy-sharing credentials are stored in the device Keychain. Profiles are stored in the app container with iOS data protection.</p><h2 id="at-your-direction" tabindex="-1">At your direction <a class="header-anchor" href="#at-your-direction" aria-label="Permalink to “At your direction”">​</a></h2><p>Clash makes external requests only to provide features you configure or start, including:</p><ul><li>subscription, provider, proxy, and DNS servers named by your configuration;</li><li>resource-update sources shown in the app;</li><li>network-quality, STUN, and latency-test endpoints you select;</li><li>your iCloud account when you explicitly create an iCloud backup.</li></ul><p>Those services receive the network information needed to perform the operation, such as your IP address. Data travels directly to the services you choose, with the developer outside that path.</p><h2 id="under-your-control" tabindex="-1">Under your control <a class="header-anchor" href="#under-your-control" aria-label="Permalink to “Under your control”">​</a></h2><p>You can disconnect, remove profiles, disable configured updates, delete local data, remove iCloud backups, and decide whether to export any diagnostic information.</p><p>The <a href="/clash.md/privacy">Privacy Policy</a> is the authoritative legal description.</p>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};